function Replay([string]$Text){
 $Text=$Text.Replace('protected ','public ').Replace('ref ','').Replace('GetGame()','Runtime.Game').Replace('System.GetTickCount()','Runtime.Now').Replace('EntityID','long').Replace('vector','V')
 $Text=[regex]::Replace($Text,'(?m)^class (AICF_\w+)','public class $1 : N')
 $Text=[regex]::Replace($Text,'array<([^>]+)>','EArray<$1>')
 $Text=[regex]::Replace($Text,'(EArray<([^>]+)>\s+\w+\s*=\s*)\{\};','$1new EArray<$2>();')
 $Text=[regex]::Replace($Text,'foreach \(([^:]+) : ([^)]+)\)','foreach ($1 in $2)')
 $Text=[regex]::Replace($Text,'for \(int (\w+);','for (int $1 = 0;')
 $Text=[regex]::Replace($Text,'(?<![\w.])(\d+\.\d+)(?![\w.])','$1f')
 $Text=[regex]::Replace($Text,'(?m)^(\s*)(static (?:bool|AICF_\w+)|bool|AIAgent|SCR_AIGroup|AICF_\w+|BaseWorld|V|float|int|string|AIWaypoint) (\w+)\(','$1public $2 $3(')
 $Text=$Text.Replace('public public ','public ')
 $Text=[regex]::Replace($Text,'(?m)^(\s*)(AICF_\w+) (endingHold|holdIntent|pending|retirementOutcome);','$1$2 $3 = null;')
 $Text=[regex]::Replace($Text,'FindComponent\((SCR_AIUtilityComponent|RplComponent)\)','FindComponent(typeof($1))')
 return $Text
}
