public static class Cases{
public static SCR_AIGroup G;public static AICF_TransportTrip T;public static AICF_VehicleSpawner Spawner;public static AICF_VehicleSpawnPlan P;public static ChimeraCharacter C;public static AIAgent Agent;public static AICF_AcquisitionStagingReceipt R;public static AIWaypoint W;public static AICF_VehicleAcquisitionHold H;public static SCR_AIDefendActivity Action;public static long Next;
public static E Register<E>(E e)where E:IEntity{e.Id=++Next;e.Rpl="R"+e.Id;e.World=Runtime.Game.World;e.World.Entities[e.Id]=e;return e;}
public static void Setup(){Runtime.Now=1000;Runtime.Game=new Game();Runtime.Events.Clear();Runtime.OnDelete=null;Replication.Server=true;Next=100;G=Register(new SCR_AIGroup());G.Utility.m_Owner=G;P=new AICF_VehicleSpawnPlan();T=new AICF_TransportTrip{Assignment=new AICF_StrategicAssignmentSnapshot{Group=G},Request=new AICF_VehicleRequestState{Plan=P},Slot=new AICF_GroupSlot{Group=G}};Spawner=new AICF_VehicleSpawner();for(int i=0;i<2;i++){var c=Register(new ChimeraCharacter{Position=new V(i,0)});var a=Register(new AIAgent{Actor=c,Group=G});c.Control.Agent=a;a.Utility.m_OwnerEntity=c;G.Agents.Add(a);C=c;Agent=a;}R=null;H=null;W=null;Action=null;}
public static AICF_AcquisitionStagingReceipt Capture(){return AICF_AcquisitionStagingReceipt.Capture(T,Spawner,5,20,1000);}
public static void Bind(){R=Capture();if(R==null)throw new Exception("valid receipt failed");W=Register(new SCR_DefendWaypoint{Position=P.Staging});H=AICF_VehicleAcquisitionHold.Capture(R,W);if(H==null||!P.BindAcquisitionHold(H))throw new Exception("valid hold failed");G.Queue.Add(W);G.Current=W;Action=new SCR_AIDefendActivity{m_RelatedWaypoint=W};G.Utility.Current=G.Utility.Executed=Action;}
public static void Need(bool value,string label){if(!value)throw new Exception(label);}
public static int Run(){int n=0;Setup();Need(!AICF_VehicleStagingTaskProof.HasCurrentTask(T,7,1000),"old SPAWN_COMMIT lacks actual actor/group task");Bind();Need(H.HasCurrentTask(T,7,1000),"real current owned RUNNING Defend task");Need(!AICF_VehicleStagingTaskProof.HasCurrentTask(T,7,1000),"old proof remains approach-only, no blanket phase exemption");n+=3;
foreach(string reason in new[]{"VEHICLE_QUOTA_PENDING","SPAWN_COMMIT_CAP_WAIT","SPAWN_BACKOFF"}){Setup();var o=new AICF_TripOutcome{Reason=reason};var r=Capture();Need(AICF_VehicleAcquisitionHold.IsWaitOutcome(o)&&o.BindAcquisitionStagingReceipt(r),"typed WAIT receipt "+reason);Need(!o.BindAcquisitionStagingReceipt(r),"receipt bind once");n+=2;}
foreach(string reason in new[]{"NATIVE_CENSUS_UNKNOWN","APPROACHING_SITE","LEASE_RESERVED_FOR_ATTACH","","ARBITRARY_WAIT"}){Setup();var o=new AICF_TripOutcome{Reason=reason};Need(!AICF_VehicleAcquisitionHold.IsWaitOutcome(o)&&!o.BindAcquisitionStagingReceipt(Capture()),"untyped reason "+reason);n++;}
Setup();var end=new AICF_TripOutcome{Kind=AICF_ETripOutcomeKind.END};Need(!AICF_VehicleAcquisitionHold.IsWaitOutcome(end)&&!end.BindAcquisitionStagingReceipt(Capture()),"END is not wait");n++;
