$taskRetirementCases=@'
public static class RetirementCases{
public static AICF_TransportTripController Controller;public static AICF_FactionFleet Fleet=new AICF_FactionFleet();public static SCR_CampaignFaction Faction=new SCR_CampaignFaction();
public static void Setup(){Lifecycle.Setup();bool s;Cases.Need(Lifecycle.Maintain(out s),"retirement setup");Controller=new AICF_TransportTripController{m_Handoff=Lifecycle.Owner,m_WaypointFactory=Lifecycle.Factory};}
