public static AICF_TripOutcome Tick(){return Controller.TickPreflight(Cases.T,Cases.T.Assignment,Cases.T.Slot,Fleet,Faction);}
public static int Run(){int n=0;Setup();var h=Cases.P.GetAcquisitionHold();Cases.G.RefuseRemove=true;var o=End();Cases.Need(o.Reason=="ACQUISITION_HOLD_RELEASE_PENDING"&&h.GetRetirement()!=null&&!Cases.T.Terminal&&Controller.Transitions==0,"failed cleanup latches retirement before End");n++;
Cases.Need(!h.IsCurrent(Cases.T,1000),"retiring hold cannot satisfy meaningful task");n++;
for(int i=0;i<3;i++){o=Tick();Cases.Need(o.Reason=="ACQUISITION_HOLD_RELEASE_PENDING"&&Controller.FlowCalls==0&&Controller.EconomyCalls==0&&Controller.m_AcquisitionFlow.Cancels==0&&Cases.P.GetAcquisitionHold()==h&&!Cases.T.Terminal,"pending retirement gates every Tick before Flow/economy");n++;}
Cases.G.RefuseRemove=false;Runtime.Events.Clear();o=Tick();Cases.Need(o.Reason=="ORIGINAL_END"&&o.Cause=="original-cause"&&Controller.TransitionReason=="ORIGINAL_END"&&Controller.TransitionCause=="original-cause"&&Controller.TransitionPhase==AICF_ETransportTripPhase.FALLBACK&&Controller.Transitions==1&&Lifecycle.Owner.Restores==1&&Cases.T.Terminal&&Controller.FlowCalls==0&&Controller.EconomyCalls==0,"retry resumes exact original terminal payload and restore");Cases.Need(string.Join(",",Runtime.Events).StartsWith("detach,stateclear,delete,utilitydetach")&&Controller.m_AcquisitionFlow.Cancels==1,"cleanup completed before terminal effects");n+=2;
Setup();h=Cases.P.GetAcquisitionHold();Cases.G.RefuseRemove=true;End();var original=h.GetRetirement();Cases.Need(h.BeginRetirement(Cases.T,Cases.T.Slot,Cases.P,AICF_ETransportTripPhase.BOARDING,"REPLACE","replace",false)&&h.GetRetirement()==original&&original.GetReason()=="ORIGINAL_END","BeginRetirement immutable bind once");n++;o=Controller.EndVehicleControl(Cases.T,Cases.T.Slot,Fleet,Faction,AICF_ETransportTripPhase.BOARDING,"OTHER","other",false);Cases.Need(h.GetRetirement()==original&&original.GetReason()=="ORIGINAL_END"&&original.RestoreCurrentOrder()&&Controller.Transitions==0,"later End cannot replace pending immutable intent");n++;
Setup();o=Tick();Cases.Need(o.Reason=="FLOW_BOUNDARY"&&Controller.FlowCalls==1&&Controller.EconomyCalls==1&&Cases.P.GetAcquisitionHold().GetRetirement()==null,"queued EVALUATED Defend without intent continues acquisition");n++;
foreach(string k in new[]{"activeAsset","phase","assignmentRevision","presetStale","bodyDead","timeExpired"}){Setup();h=Cases.P.GetAcquisitionHold();Cases.G.RefuseRemove=true;End();switch(k){case"activeAsset":Cases.T.Lease=new AICF_VehicleLease{Physical=true,State=AICF_EVehicleLeaseState.ACTIVE};break;case"phase":Cases.T.Phase=AICF_ETransportTripPhase.BOARDING;break;case"assignmentRevision":Cases.T.Assignment.Assignment++;Cases.T.Slot.Assignment++;break;case"presetStale":Cases.T.PresetCurrent=false;break;case"bodyDead":Cases.C.Conscious=false;break;case"timeExpired":Runtime.Now=25000;break;}for(int i=0;i<2;i++){o=Tick();Cases.Need(Controller.FlowCalls==0&&Controller.EconomyCalls==0&&Controller.Transitions==0&&!Cases.T.Terminal&&Cases.P.GetAcquisitionHold()==h,"pending retirement no Flow after mutable task loss/"+k);n++;}Cases.G.RefuseRemove=false;o=Tick();Cases.Need(Controller.FlowCalls==0&&Controller.EconomyCalls==0&&h.GetWaypoint().Deleted,"owned cleanup after mutable task loss/"+k);if(k=="phase"||k=="assignmentRevision")Cases.Need(Controller.Transitions==0&&!Cases.T.Terminal,"changed epoch cleanup does not End successor/"+k);else Cases.Need(Controller.Transitions==1&&Cases.T.Terminal,"same epoch original End after task loss/"+k);n++;}
foreach(string k in new[]{"groupGen","tripGen","requestGen","intentRev","baseRev","presetRev","phase","slotIntent","slotPreset","assignmentPtr","requestPtr","planPtr","slotPtr"}){Setup();h=Cases.P.GetAcquisitionHold();Cases.G.RefuseRemove=true;End();var intent=h.GetRetirement();switch(k){case"groupGen":Cases.T.Generation++;break;case"tripGen":Cases.T.TripGeneration++;break;case"requestGen":Cases.T.Request.Generation++;break;case"intentRev":Cases.T.Assignment.Intent++;break;case"baseRev":Cases.T.Assignment.BaseRevision++;break;case"presetRev":Cases.T.PresetRevision++;break;case"phase":Cases.T.Phase=AICF_ETransportTripPhase.BOARDING;break;case"slotIntent":Cases.T.Slot.Intent++;break;case"slotPreset":Cases.T.Slot.PresetRevision++;break;case"assignmentPtr":Cases.T.Assignment=new AICF_StrategicAssignmentSnapshot{Group=Cases.G};break;case"requestPtr":Cases.T.Request=new AICF_VehicleRequestState{Plan=Cases.P};break;case"planPtr":Cases.T.Request.Plan=new AICF_VehicleSpawnPlan();break;case"slotPtr":Cases.T.Slot=new AICF_GroupSlot{Group=Cases.G};break;}Cases.Need(!intent.IsEpochCurrent(Cases.T,Cases.T.Slot,false),"immutable retirement epoch/"+k);AICF_TripOutcome result;Controller.TryFinishAcquisitionHoldRetirement(Cases.T,Cases.T.Assignment,Cases.T.Slot,Fleet,Faction,out result);Cases.Need(Controller.Transitions==0&&Lifecycle.Owner.Restores==0&&!Cases.T.Terminal,"stale intent cannot terminate successor/"+k);n++;}
Setup();h=Cases.P.GetAcquisitionHold();Cases.G.RefuseRemove=true;End();Cases.G.RefuseRemove=false;AICF_VehicleAcquisitionHold successor=null;Cases.G.OnRemove=w=>{Cases.G.OnRemove=null;Cases.P.ClearAcquisitionHold(h);bool s;Cases.Need(Lifecycle.Maintain(out s),"retirement callback successor setup");successor=Cases.P.GetAcquisitionHold();};o=Tick();Cases.Need(o.Reason=="ACQUISITION_HOLD_RETIREMENT_SUPERSEDED"&&successor!=null&&Cases.P.GetAcquisitionHold()==successor&&!successor.GetWaypoint().Deleted&&!Cases.T.Terminal&&Controller.Transitions==0&&Controller.FlowCalls==0,"reentrant removal successor survives and no original End");n++;
Setup();h=Cases.P.GetAcquisitionHold();Cases.G.RefuseRemove=true;End();Cases.G.RefuseRemove=false;Controller.m_AcquisitionFlow.OnCancel=()=>Cases.T.TripGeneration++;o=Tick();Cases.Need(o.Reason=="ACQUISITION_HOLD_RETIREMENT_SUPERSEDED"&&Controller.Transitions==0&&!Cases.T.Terminal,"cancel callback epoch repeated before End");n++;
Cases.Setup();Cases.P.Staging=new V(0,0){Y=25};Cases.R=Cases.Capture();Cases.W=Cases.Register(new SCR_DefendWaypoint{Position=new V(0,0){Y=7}});Cases.H=AICF_VehicleAcquisitionHold.Capture(Cases.R,Cases.W);Cases.Need(Cases.H!=null&&Cases.P.BindAcquisitionHold(Cases.H)&&Cases.H.IsCurrent(Cases.T,1000),"navmesh Y differs from surface Y with exact initial XZ");Cases.W.Position=new V(0,0){Y=8};Cases.Need(!Cases.H.IsCurrent(Cases.T,1000),"captured actual Y immutable");n+=2;
foreach(string axis in new[]{"X","Z"}){Cases.Setup();Cases.R=Cases.Capture();Cases.W=Cases.Register(new SCR_DefendWaypoint{Position=axis=="X"?new V(.001f,0):new V(0,.001f)});Cases.Need(AICF_VehicleAcquisitionHold.Capture(Cases.R,Cases.W)==null,"initial XZ exact no widening/"+axis);n++;}
return n;}}
