$taskMutants=@(
 @('authority','!Replication.IsServer()','false'),
 @('phase','trip.GetPhase() != AICF_ETransportTripPhase.SPAWN_COMMIT','false'),
 @('bodyAuthority','!AICF_VehicleBoardingMutationFence.IsAuthoritativeAIEntity(m_Actor)','false'),
