)
$taskCaught=0
foreach($taskMutation in $taskMutants){
 if(!$taskCompiled.Contains($taskMutation[1])){throw "Executable mutation target missing: $($taskMutation[0])"}
 $taskNS='StagingHoldUnsafe'+$taskMutation[0]
 $taskReplacement=$taskMutation[2]
 if($taskReplacement-eq'false'){$taskReplacement='ReplayGuard.Off()'}elseif($taskReplacement-eq'true'){$taskReplacement='ReplayGuard.On()'}else{$taskReplacement=$taskReplacement.Replace('if (false)','if (ReplayGuard.Off())')}
 $taskVariant=$taskCompiled.Replace('StagingHoldReplay',$taskNS).Replace($taskMutation[1],$taskReplacement)
 if($taskMutation[0]-eq'tripDeadlineIdentity'){$taskVariant=$taskVariant.Replace('trip.AcquisitionHoldDeadlineAtMs(m_iCapturedAtMs) != m_iTripDeadline','ReplayGuard.Off()')}
 if($taskMutation[0]-eq'freshClockTask'){$taskTaskBody=Replay (Body $taskHold 'HasCurrentTask');$taskVariant=$taskVariant.Replace($taskTaskBody,$taskTaskBody.Replace('Runtime.Now','nowMs'))}
 Add-Type -TypeDefinition $taskVariant -Language CSharp
 $taskRejected=$false
 try{[void]([type]($taskNS+'.Cases')).GetMethod('Run').Invoke($null,@())}catch{$taskRejected=$true}
